tokens:
--scheme: light;
color-scheme: light;
--bg: #f7f5ef;
--bg2: #efece3;
--surface: #fffefa;
--surface2: #ece8dc;
--ink: #22232a;
--muted: #3f414a;
--faint: #575a63;
--cardmeta: #2e3038;
--gold: #2b50a6;
--gold-soft: #1f3d85;
--gold-deep: #22232a;
--on-gold: #ffffff;
--ink-soft: #3f414a;
--line: rgba(34, 35, 42, 0.18);
--line-strong: #2b50a6;
--ok: #1f6b33;
--warn: #7f5800;
--bad: #b0220f;
--shadow: 0 1px 1px rgba(40, 40, 52, 0.14), 0 6px 0 -2px rgba(40, 40, 52, 0.10), 0 10px 18px rgba(40, 40, 52, 0.10);
--elev-1: 0 1px 1px rgba(40, 40, 52, 0.14), 0 3px 6px rgba(40, 40, 52, 0.10);
--elev-2: 0 2px 2px rgba(40, 40, 52, 0.14), 0 10px 22px rgba(40, 40, 52, 0.14);
--elev-3: 0 4px 6px rgba(40, 40, 52, 0.16), 0 24px 60px rgba(40, 40, 52, 0.22);
--scrim: rgba(34, 35, 42, 0.42);
--focus: #2f6fd6;
--th-bg: #ece8dc;
--tabgrad1: #ece8dc; --tabgrad2: #fffefa;
--toastgrad1: #ece8dc; --toastgrad2: #fffefa;
--foot-bg: rgba(247, 245, 239, 0.95);
--drawerbar-bg: rgba(255, 254, 250, 0.96);
--ph-bg: #ece8dc;
--sel-bg: rgba(43, 80, 166, 0.15);
--row-hover: rgba(43, 80, 166, 0.07);
--hold-bg: linear-gradient(135deg, #ece8dc, #fffefa);
--skeleton1: #ece8dc; --skeleton2: #f7f5ef;
--grain-op: 0.035;
--wing-dur: 0.42s;
--wing-rise: 14px;
/* legacy aliases resolved on <html> */
--text: var(--ink); --panel: var(--surface); --chip: var(--surface2); --missing: var(--faint);
--border: var(--line); --gold-dim: var(--gold-deep); --danger: var(--bad);
--serif: "Avenir Next", "Segoe UI", "Trebuchet MS", system-ui, -apple-system, sans-serif;
--hand: "Segoe Print", "Bradley Hand", "Chalkboard SE", "Comic Sans MS", "Marker Felt", cursive;
--radius: 14px;
/* the pencil lines of the sketch treatment (styles/style-layer.css, ui "sketch") */
--sk-line: rgba(34, 35, 42, 0.78);
--sk-echo: rgba(34, 35, 42, 0.30);
/* the dark display-case interior used by the instrument panels (styles/style-layer.css, ui "paper"): a graphite sketchbook cover */
--case-bg: #26282f;
--case-bg2: #2c2e36;
--case-surface: #33363f;
--case-surface2: #3e414b;
--case-ink: #ffffff;
--case-muted: #dfe1e8;
--case-faint: #bfc2cc;
--case-gold: #a9c1ff;
--case-gold-soft: #d2deff;
--case-on-gold: #26282f;
/* the page palette again, for paper labels inside a case */
--paper-bg: #f7f5ef;
--paper-bg2: #efece3;
--paper-surface: #fffefa;
--paper-surface2: #ece8dc;
--paper-ink: #22232a;
--paper-muted: #3f414a;
--paper-faint: #575a63;
--paper-gold: #2b50a6;
--paper-gold-soft: #1f3d85;
--paper-on-gold: #ffffff;

scene:
{ world: true, name: "Sketchbook", icon: "✏️", desc: "A quiet art room: pages turning, a clock, rain on the window, soft keys.", atmo: "sketch",
               beds: { roomTone: 0.35, pages: 0.45, clock: 0.28, rainWindow: 0.14 }, pad: 0.35, piano: true, bells: false, beat: false,
               root: "F", mode: "lydian", prog: [0, 3, 4, 0], chordSec: 0, gap: [6, 12], bpm: 74, vol: 0.45 }
